import ghidra.app.decompiler.DecompInterface;
import ghidra.app.decompiler.DecompileResults;
import ghidra.app.script.GhidraScript;
import ghidra.program.model.address.Address;
import ghidra.program.model.listing.Function;

public class DumpDecomp extends GhidraScript {
    @Override
    public void run() throws Exception {
        String[] args = getScriptArgs();
        PrintWriter output = new PrintWriter(new File(args[0]));
        DecompInterface decompiler = new DecompInterface();
        decompiler.toggleCCode(true);
        decompiler.toggleSyntaxTree(true);
        decompiler.setSimplificationStyle("decompile");
        decompiler.openProgram(currentProgram);
        for (int index = 1; index < args.length; index++) {
            Address address = toAddr(args[index]);
            Function function = getFunctionContaining(address);
            if (function == null) {
                output.println("NO FUNCTION AT " + address);
                continue;
            }
            output.println("/* " + function.getName() + " @ " + function.getEntryPoint() + " */");
            DecompileResults results = decompiler.decompileFunction(function, 120, monitor);
            if (results.decompileCompleted()) {
                output.println(results.getDecompiledFunction().getC());
            } else {
                output.println("DECOMPILATION FAILED: " + results.getErrorMessage());
            }
        }
        output.close();
        decompiler.dispose();
    }
}
